ProgramUnit.ProgramUnitText:
PACKAGE ui IS
  PROCEDURE init;
  PROCEDURE press(p_item VARCHAR2);
  PROCEDURE tool(p_item VARCHAR2);
  PROCEDURE dblclick(p_item VARCHAR2);
  PROCEDURE validate(p_item VARCHAR2);
  PROCEDURE post_query(p_block VARCHAR2);
  PROCEDURE master(p_block VARCHAR2);
  PROCEDURE on_error(p_code NUMBER, p_type VARCHAR2, p_text VARCHAR2, p_dbtext VARCHAR2);
  FUNCTION friendly(p_dbtext VARCHAR2) RETURN VARCHAR2;
END;

PACKAGE BODY ui IS
  c_block CONSTANT VARCHAR2(30) := 'DOC';
  c_where CONSTANT VARCHAR2(400) := 'doc_type in (''TPY'', ''PPY'', ''TAG'', ''PAG'')';
  c_detail CONSTANT VARCHAR2(30) := 'DL';
  c_detail2 CONSTANT VARCHAR2(30) := 'DS';
  g_master NUMBER;                  -- the master whose detail is on the screen
  g_detail NUMBER;                  -- the record of the detail whose own detail is on the screen

  FUNCTION num(p_item VARCHAR2) RETURN NUMBER IS
  BEGIN
    RETURN to_number(name_in(p_item));
  END;

  FUNCTION tx(p_key VARCHAR2) RETURN VARCHAR2 IS
  BEGIN
    RETURN mm_text.t(p_key);
  END;

  PROCEDURE fail(p_msg VARCHAR2) IS
  BEGIN
    message(p_msg);
    RAISE form_trigger_failure;
  END;

  PROCEDURE init IS
  BEGIN
    SET_WINDOW_PROPERTY('WIN', TITLE, tx('TAA924921'));
    SET_MENU_ITEM_PROPERTY('MAIN_MENU.FILE', LABEL, tx('TDE2E2563'));
    SET_MENU_ITEM_PROPERTY('FILE_MENU.MAIN', LABEL, tx('T4D1390F6'));
    SET_MENU_ITEM_PROPERTY('FILE_MENU.EXIT', LABEL, tx('T1BDD3E84'));
    SET_MENU_ITEM_PROPERTY('MAIN_MENU.REC', LABEL, tx('TC8D30D55'));
    SET_MENU_ITEM_PROPERTY('REC_MENU.SAVE', LABEL, tx('TC4CBA576'));
    SET_MENU_ITEM_PROPERTY('REC_MENU.ENTERQ', LABEL, tx('TCFB2C237'));
    SET_MENU_ITEM_PROPERTY('REC_MENU.EXECQ', LABEL, tx('TCBEE6CE0'));
    SET_MENU_ITEM_PROPERTY('REC_MENU.NEWREC', LABEL, tx('TA4B62D60'));
    SET_MENU_ITEM_PROPERTY('REC_MENU.DELREC', LABEL, tx('T2667D3EB'));
    SET_MENU_ITEM_PROPERTY('REC_MENU.LOV', LABEL, tx('T15E12A4A'));
    SET_MENU_ITEM_PROPERTY('MAIN_MENU.STOCK', LABEL, tx('T03CB8CFA'));
    SET_MENU_ITEM_PROPERTY('STOCK_MENU.ITEMS', LABEL, tx('T3DB645A5'));
    SET_MENU_ITEM_PROPERTY('STOCK_MENU.VARIANTS', LABEL, tx('T7A02795A'));
    SET_MENU_ITEM_PROPERTY('STOCK_MENU.KITS', LABEL, tx('T8A7F4F4B'));
    SET_MENU_ITEM_PROPERTY('STOCK_MENU.CARDS', LABEL, tx('T533C6207'));
    SET_MENU_ITEM_PROPERTY('MAIN_MENU.SALES', LABEL, tx('TF6273FDC'));
    SET_MENU_ITEM_PROPERTY('SALES_MENU.INVOICES', LABEL, tx('T3928F84E'));
    SET_MENU_ITEM_PROPERTY('SALES_MENU.RECEIPTS', LABEL, tx('T8633F926'));
    SET_MENU_ITEM_PROPERTY('SALES_MENU.CUSTOMERS', LABEL, tx('TF89F7153'));
    SET_MENU_ITEM_PROPERTY('SALES_MENU.RESERV', LABEL, tx('TB3823DFC'));
    SET_MENU_ITEM_PROPERTY('SALES_MENU.PROMOS', LABEL, tx('TDFA28B6D'));
    SET_MENU_ITEM_PROPERTY('MAIN_MENU.BUY', LABEL, tx('T6F7093C3'));
    SET_MENU_ITEM_PROPERTY('BUY_MENU.PINVOICES', LABEL, tx('T7CE3A1B0'));
    SET_MENU_ITEM_PROPERTY('BUY_MENU.PAYMENTS', LABEL, tx('T8BFEAB12'));
    SET_MENU_ITEM_PROPERTY('BUY_MENU.SUPPLIERS', LABEL, tx('TDC480307'));
    SET_ITEM_PROPERTY('DOC.DOC_TYPE', PROMPT_TEXT, tx('TC6CCBB99'));
    SET_ITEM_PROPERTY('DOC.DOC_NO', PROMPT_TEXT, tx('TAE7E7E75'));
    SET_ITEM_PROPERTY('DOC.DOC_DATE', PROMPT_TEXT, tx('T96EA7CBE'));
    SET_ITEM_PROPERTY('DOC.STATUS', PROMPT_TEXT, tx('T2A8EC049'));
    SET_ITEM_PROPERTY('DOC.PARTNER_TEXT', PROMPT_TEXT, tx('TDD4BFC21'));
    SET_ITEM_PROPERTY('DOC.PAYMENT', PROMPT_TEXT, tx('TC06F95F5'));
    SET_ITEM_PROPERTY('DOC.NET', PROMPT_TEXT, tx('T33C17131'));
    SET_ITEM_PROPERTY('DOC.VAT', PROMPT_TEXT, tx('T3CCA1645'));
    SET_ITEM_PROPERTY('DOC.TOTAL', PROMPT_TEXT, tx('T7EF56116'));
    SET_ITEM_PROPERTY('DL.ITEM_TEXT', PROMPT_TEXT, tx('TC6CCBB99'));
    SET_ITEM_PROPERTY('DL.QTY', PROMPT_TEXT, tx('T3BB79963'));
    SET_ITEM_PROPERTY('DL.PRICE', PROMPT_TEXT, tx('T39DDE2FF'));
    SET_ITEM_PROPERTY('DL.DISCOUNT', PROMPT_TEXT, tx('TF8781DB1'));
    SET_ITEM_PROPERTY('DL.PROMO_DISC', PROMPT_TEXT, tx('T48E3028B'));
    SET_ITEM_PROPERTY('DL.NET', PROMPT_TEXT, tx('T33C17131'));
    SET_ITEM_PROPERTY('DL.VAT', PROMPT_TEXT, tx('T3CCA1645'));
    SET_ITEM_PROPERTY('DL.TOTAL', PROMPT_TEXT, tx('T7EF56116'));
    SET_ITEM_PROPERTY('DS.SERIAL', PROMPT_TEXT, tx('TC2FDAE35'));
    SET_ITEM_PROPERTY('DS.STATUS', PROMPT_TEXT, tx('T2A8EC049'));
    SET_ITEM_PROPERTY('CTL.FIND', LABEL, tx('T996015D1'));
    SET_ITEM_PROPERTY('CTL.ALL', LABEL, tx('T382D5390'));
    SET_ITEM_PROPERTY('CTL.D_TYPE', PROMPT_TEXT, tx('T50152A6A'));
    SET_ITEM_PROPERTY('CTL.CUST_TEXT', PROMPT_TEXT, tx('T3008E1C6'));
    SET_ITEM_PROPERTY('CTL.SUPP_TEXT', PROMPT_TEXT, tx('T9B91F010'));
    SET_ITEM_PROPERTY('CTL.D_PAY', PROMPT_TEXT, tx('TC06F95F5'));
    SET_ITEM_PROPERTY('CTL.D_DATE', PROMPT_TEXT, tx('T96EA7CBE'));
    SET_ITEM_PROPERTY('CTL.NEWDOC', LABEL, tx('TCA45AA77'));
    SET_ITEM_PROPERTY('CTL.POSTDOC', LABEL, tx('T084AD196'));
    SET_ITEM_PROPERTY('CTL.CANCELDOC', LABEL, tx('TE3E64FBC'));
    SET_ITEM_PROPERTY('CTL.CREDIT', LABEL, tx('T1AA9AB25'));
    SET_ITEM_PROPERTY('CTL.DELDOC', LABEL, tx('TD8FF2388'));
    SET_ITEM_PROPERTY('CTL.L_ITEM_TEXT', PROMPT_TEXT, tx('T50152A6A'));
    SET_ITEM_PROPERTY('CTL.L_QTY', PROMPT_TEXT, tx('T3BB79963'));
    SET_ITEM_PROPERTY('CTL.L_PRICE', PROMPT_TEXT, tx('T39DDE2FF'));
    SET_ITEM_PROPERTY('CTL.L_DISC', PROMPT_TEXT, tx('TF8781DB1'));
    SET_ITEM_PROPERTY('CTL.ADDLINE', LABEL, tx('T2F92EEAC'));
    SET_ITEM_PROPERTY('CTL.DELLINE', LABEL, tx('T2C8395CE'));
    SET_ITEM_PROPERTY('CTL.S_SERIAL', PROMPT_TEXT, tx('TB40E90F7'));
    SET_ITEM_PROPERTY('CTL.S_PIN', PROMPT_TEXT, tx('TBD2C56DE'));
    SET_ITEM_PROPERTY('CTL.ADDSER', LABEL, tx('T3D9F54AD'));
    SET_ITEM_PROPERTY('CTL.DELSER', LABEL, tx('T2ADEE740'));
    SET_ITEM_PROPERTY('TB.T_SAVE', LABEL, tx('TC7EEF11D'));
    SET_ITEM_PROPERTY('TB.T_ENTERQ', LABEL, tx('TB8358694'));
    SET_ITEM_PROPERTY('TB.T_EXECQ', LABEL, tx('T7C00F3E1'));
    SET_ITEM_PROPERTY('TB.T_NEW', LABEL, tx('T215F064A'));
    SET_ITEM_PROPERTY('TB.T_DEL', LABEL, tx('T6192BEAA'));
    SET_ITEM_PROPERTY('TB.T_LOV', LABEL, tx('T5360A387'));
    SET_ITEM_PROPERTY('TB.T_MAIN', LABEL, tx('T6FB015C4'));
    SET_ITEM_PROPERTY('TB.T_EXIT', LABEL, tx('T1BDD3E84'));
    COPY('TPY', 'CTL.D_TYPE');
    COPY('CREDIT', 'CTL.D_PAY');
    COPY(to_char(sysdate, 'DD/MM/YYYY'), 'CTL.D_DATE');
    COPY('1', 'CTL.L_QTY');
    SET_LOV_PROPERTY('LOV_FIND', TITLE, tx('TAA924921'));
    SET_LOV_COLUMN_PROPERTY('LOV_FIND', 1, TITLE, tx('T4491B68A'));
    SET_LOV_COLUMN_PROPERTY('LOV_FIND', 2, TITLE, tx('T173D0C72'));
    SET_LOV_COLUMN_PROPERTY('LOV_FIND', 3, TITLE, tx('TDD4BFC21'));
    SET_LOV_PROPERTY('LOV_DTYPE', TITLE, tx('T43B58C87'));
    SET_LOV_COLUMN_PROPERTY('LOV_DTYPE', 1, TITLE, tx('TC6CCBB99'));
    SET_LOV_COLUMN_PROPERTY('LOV_DTYPE', 2, TITLE, tx('T32D94AD8'));
    SET_LOV_PROPERTY('LOV_CUST', TITLE, tx('TF89F7153'));
    SET_LOV_COLUMN_PROPERTY('LOV_CUST', 1, TITLE, tx('T4491B68A'));
    SET_LOV_COLUMN_PROPERTY('LOV_CUST', 2, TITLE, tx('T256B17A1'));
    SET_LOV_PROPERTY('LOV_SUPP', TITLE, tx('TDC480307'));
    SET_LOV_COLUMN_PROPERTY('LOV_SUPP', 1, TITLE, tx('T4491B68A'));
    SET_LOV_COLUMN_PROPERTY('LOV_SUPP', 2, TITLE, tx('T2BA80546'));
    SET_LOV_PROPERTY('LOV_PAY', TITLE, tx('TC06F95F5'));
    SET_LOV_COLUMN_PROPERTY('LOV_PAY', 1, TITLE, tx('TC06F95F5'));
    SET_LOV_COLUMN_PROPERTY('LOV_PAY', 2, TITLE, tx('T32D94AD8'));
    SET_LOV_PROPERTY('LOV_ITEMI', TITLE, tx('T3DB645A5'));
    SET_LOV_COLUMN_PROPERTY('LOV_ITEMI', 1, TITLE, tx('T4491B68A'));
    SET_LOV_COLUMN_PROPERTY('LOV_ITEMI', 2, TITLE, tx('TC6CCBB99'));
    IF c_block IS NOT NULL THEN          -- (the menu has no block of a table)
      go_block(c_block);
      set_block_property(c_block, DEFAULT_WHERE, c_where);
      execute_query;
    END IF;
  END;

  -- the detail of the master record on the screen (once for each master record: going back to the
  -- master brings this trigger again)
  -- (three levels: the detail is the master of c_detail2, e.g. an invoice, its lines, their serials)
  PROCEDURE master(p_block VARCHAR2) IS
    id_ NUMBER := num(p_block || '.ID');
  BEGIN
    IF id_ IS NULL THEN
      RETURN;
    END IF;
    IF p_block = c_block AND c_detail IS NOT NULL THEN
      IF id_ = g_master THEN
        RETURN;
      END IF;
      g_master := id_;
      g_detail := NULL;
      go_block(c_detail);
      execute_query;
      go_block(c_block);
    ELSIF p_block = c_detail AND c_detail2 IS NOT NULL THEN
      IF id_ = g_detail THEN
        RETURN;
      END IF;
      g_detail := id_;
      go_block(c_detail2);
      execute_query;
      go_block(c_detail);
    END IF;
  END;

  PROCEDURE again(p_block VARCHAR2) IS
  BEGIN
    g_master := NULL;
    g_detail := NULL;
    go_block(p_block);
    execute_query;
    IF p_block <> c_block THEN
      go_block(c_block);
    END IF;
  END;

  -- the register of the box CTL.REG_CODE (T1 by default)
  FUNCTION register_id RETURN NUMBER IS
    c VARCHAR2(10) := upper(nvl(name_in('CTL.REG_CODE'), 'T1'));
    r NUMBER;
  BEGIN
    SELECT id INTO r FROM mm_register WHERE code = c;
    RETURN r;
  EXCEPTION
    WHEN no_data_found THEN
      message(tx('TF8550DB9') || c);
      RAISE form_trigger_failure;
  END;

  -- the buttons of the cards and of the reservations: MM_CORE, then COMMIT (MM_CORE does not commit)
  -- a date typed in CTL (text DD/MM/YYYY: the same on every runtime)
  FUNCTION date_in(p_item VARCHAR2) RETURN DATE IS
  BEGIN
    RETURN to_date(name_in(p_item), 'DD/MM/YYYY');
  END;

  -- after a new master record made from CTL: it alone on the screen
  PROCEDURE show_only(p_id NUMBER) IS
  BEGIN
    go_block(c_block);
    set_block_property(c_block, DEFAULT_WHERE, 'id = ' || to_char(p_id));
    again(c_block);
  END;

  PROCEDURE action(p_item VARCHAR2) IS
    v NUMBER;
    n NUMBER;
    s NUMBER;
    pin VARCHAR2(40);
    tr VARCHAR2(1);
    sd VARCHAR2(1);
  BEGIN
    IF p_item LIKE 'CTL.GO\_%' ESCAPE '\' THEN           -- the menu: the form of the button
      call_form(substr(p_item, 8));
      RETURN;
    ELSIF p_item = 'CTL.EXIT' THEN
      exit_form;
      RETURN;
    ELSIF p_item = 'CTL.LOAD' THEN
      v := num('CARD.ID');
      n := mm_core.load_serial(v, name_in('CTL.NEW_SERIAL'), name_in('CTL.NEW_PIN'));
      forms_ddl('COMMIT');
      copy('', 'CTL.NEW_SERIAL');
      copy('', 'CTL.NEW_PIN');
      SELECT stock INTO s FROM mm_item WHERE id = v;
      copy(to_char(s), 'CARD.STOCK');
      again('SER');
      message(tx('TC206764A'));
    ELSIF p_item = 'CTL.PIN' THEN
      pin := mm_core.reveal_pin(num('SER.ID'), name_in('CTL.USERNAME'));
      forms_ddl('COMMIT');                                     -- the log of who saw it
      copy(pin, 'SER.PIN_SHOW');
    ELSIF p_item = 'CTL.NEWRES' THEN
      v := mm_core.new_reservation(name_in('CTL.R_NAME'), name_in('CTL.R_PHONE'), date_in('CTL.R_DATE'));
      forms_ddl('COMMIT');
      copy('', 'CTL.R_NAME');
      copy('', 'CTL.R_PHONE');
      show_only(v);
      message(tx('TB38DB8DE') || to_char(v) || tx('T6B6F1E68'));
    ELSIF p_item = 'CTL.RESERVE' THEN
      mm_core.reserve(num('RES.ID'), num('CTL.ITEM_ID'), nvl(num('CTL.QTY'), 1));
      forms_ddl('COMMIT');
      again('RL');
    ELSIF p_item = 'CTL.DEPOSIT' THEN
      mm_core.take_deposit(num('RES.ID'), register_id, num('CTL.AMOUNT'), upper(nvl(name_in('CTL.PAY'), 'CASH')));
      forms_ddl('COMMIT');
      copy('', 'CTL.AMOUNT');
      again(c_block);
      message(tx('T2C5C9903'));
    ELSIF p_item = 'CTL.DELIVER' THEN
      v := mm_core.deliver(num('RES.ID'), register_id, upper(nvl(name_in('CTL.PAY'), 'CASH')));
      n := mm_core.post_doc(v);
      forms_ddl('COMMIT');
      again(c_block);
      message(tx('T34D71890') || to_char(n));
    ELSIF p_item = 'CTL.CANCELRES' THEN
      mm_core.cancel_reservation(num('RES.ID'), register_id, 'Y');
      forms_ddl('COMMIT');
      again(c_block);
      message(tx('TEDC19F4B'));
    -- the baskets: a component in or out (0), a new basket from an item, assemble (negative: apart)
    ELSIF p_item = 'CTL.ADDCOMP' THEN
      v := nvl(num('CTL.NEWKIT_ID'), num('KIT.ID'));
      mm_core.set_component(v, num('CTL.COMP_ID'), nvl(num('CTL.COMP_QTY'), 1));
      forms_ddl('COMMIT');
      copy('', 'CTL.COMP_ID');
      copy('', 'CTL.COMP_TEXT');
      IF name_in('CTL.NEWKIT_ID') IS NOT NULL THEN
        copy('', 'CTL.NEWKIT_ID');
        copy('', 'CTL.NEWKIT_TEXT');
        show_only(v);
      ELSE
        again('KC');
      END IF;
    ELSIF p_item = 'CTL.ASSEMBLE' THEN
      n := num('CTL.ASM_QTY');
      mm_core.assemble_kit(num('KIT.ID'), n);
      forms_ddl('COMMIT');
      again(c_block);
      message(tx('T8EB30B22') || to_char(n));
    -- the promotions: new, an item or a category in (0: out), active or not
    ELSIF p_item = 'CTL.NEWPROMO' THEN
      v := mm_core.new_promo(name_in('CTL.P_NAME'), upper(name_in('CTL.P_KIND')), date_in('CTL.P_FROM'), date_in('CTL.P_TO'),
                             num('CTL.P_PCT'), num('CTL.P_BUY'), num('CTL.P_FREE'), num('CTL.P_PRICE'));
      forms_ddl('COMMIT');
      copy('', 'CTL.P_NAME');
      show_only(v);
      message(tx('T1BB907E2'));
    ELSIF p_item = 'CTL.ADDPI' THEN
      mm_core.promo_item(num('PROMO.ID'), num('CTL.PI_ITEM_ID'), num('CTL.PI_CAT_ID'), nvl(num('CTL.PI_QTY'), 1));
      forms_ddl('COMMIT');
      copy('', 'CTL.PI_ITEM_ID');
      copy('', 'CTL.PI_ITEM_TEXT');
      copy('', 'CTL.PI_CAT_ID');
      copy('', 'CTL.PI_CAT_TEXT');
      again('PI');
    ELSIF p_item = 'CTL.TOGGLE' THEN
      mm_core.promo_active(num('PROMO.ID'), CASE name_in('PROMO.ACTIVE') WHEN 'Y' THEN 'N' ELSE 'Y' END);
      forms_ddl('COMMIT');
      again(c_block);
    -- clothes and shoes: a new variant (of the model, or of an item that becomes a model), one price
    ELSIF p_item = 'CTL.NEWVAR' THEN
      v := nvl(num('CTL.NEWMODEL_ID'), num('MODEL.ID'));
      n := mm_core.make_variant(v, num('CTL.V_COLOR_ID'), num('CTL.V_SIZE_ID'), name_in('CTL.V_BARCODE'));
      forms_ddl('COMMIT');
      copy('', 'CTL.V_BARCODE');
      IF name_in('CTL.NEWMODEL_ID') IS NOT NULL THEN
        copy('', 'CTL.NEWMODEL_ID');
        copy('', 'CTL.NEWMODEL_TEXT');
        show_only(v);
      ELSE
        again('VG');
      END IF;
    ELSIF p_item = 'CTL.MPRICE' THEN
      mm_core.model_price(num('MODEL.ID'), num('CTL.M_PRICE'));
      forms_ddl('COMMIT');
      again(c_block);
    -- invoicing: a new document (alone on the screen: its totals and lines as they change), a line
    -- (a card of mobile phones in a sale: as many cards, with their serials), post, cancel, credit
    ELSIF p_item = 'CTL.NEWDOC' THEN
      v := mm_core.new_doc(upper(name_in('CTL.D_TYPE')), num('CTL.CUST_ID'), num('CTL.SUPP_ID'), NULL,
                           upper(nvl(name_in('CTL.D_PAY'), 'CREDIT')), date_in('CTL.D_DATE'));
      forms_ddl('COMMIT');
      show_only(v);
      message(tx('T11BA4162'));
    ELSIF p_item = 'CTL.ADDLINE' THEN
      v := num('DOC.ID');
      s := num('CTL.L_ITEM_ID');
      SELECT i.serial_tracked, t.side, t.stock_sign INTO tr, sd, n
      FROM mm_doc d, mm_doc_type t, mm_item i
      WHERE d.id = v AND t.code = d.doc_type AND i.id = s;
      IF tr = 'Y' AND sd = 'S' AND n = -1 THEN
        n := mm_core.sell_serials(v, s, nvl(num('CTL.L_QTY'), 1));
      ELSE
        n := mm_core.add_line(v, s, nvl(num('CTL.L_QTY'), 1), num('CTL.L_PRICE'), nvl(num('CTL.L_DISC'), 0));
      END IF;
      forms_ddl('COMMIT');
      copy('', 'CTL.L_ITEM_ID');
      copy('', 'CTL.L_ITEM_TEXT');
      copy('', 'CTL.L_PRICE');
      copy('', 'CTL.L_DISC');
      show_only(v);
    ELSIF p_item = 'CTL.DELLINE' THEN
      v := num('DOC.ID');
      mm_core.delete_line(num('DL.ID'));
      forms_ddl('COMMIT');
      show_only(v);
    ELSIF p_item = 'CTL.POSTDOC' THEN
      v := num('DOC.ID');
      n := mm_core.post_doc(v);
      forms_ddl('COMMIT');
      show_only(v);
      message(tx('T2B22DDCC') || to_char(n));
    ELSIF p_item = 'CTL.CANCELDOC' THEN
      v := num('DOC.ID');
      mm_core.cancel_doc(v);
      forms_ddl('COMMIT');
      show_only(v);
      message(tx('T21EA605F'));
    ELSIF p_item = 'CTL.CREDIT' THEN
      v := mm_core.credit_note(num('DOC.ID'));
      forms_ddl('COMMIT');
      show_only(v);
      message(tx('T8EAC73D9'));
    -- the serials of a line of cards: a sale takes this card (scanned) in its line, or gives one
    -- back; a purchase loads this card (and its PIN) in the line chosen
    ELSIF p_item = 'CTL.ADDSER' THEN
      v := num('DOC.ID');
      SELECT t.side, t.stock_sign INTO sd, n FROM mm_doc d, mm_doc_type t WHERE d.id = v AND t.code = d.doc_type;
      IF sd = 'S' AND n = -1 THEN
        n := mm_core.sell_serial(v, NULL, name_in('CTL.S_SERIAL'));
      ELSE
        n := mm_core.add_serial(num('DL.ID'), name_in('CTL.S_SERIAL'), name_in('CTL.S_PIN'));
      END IF;
      forms_ddl('COMMIT');
      copy('', 'CTL.S_SERIAL');
      copy('', 'CTL.S_PIN');
      show_only(v);
      message(tx('TC6C7AC4D'));
    ELSIF p_item = 'CTL.DELSER' THEN
      v := num('DOC.ID');
      mm_core.release_serial(num('DS.ID'));
      forms_ddl('COMMIT');
      show_only(v);
      message(tx('TFA795D41'));
    -- a receipt (R) or a payment (P); with a register (CTL.REG_CODE): a move of its open Z too
    ELSIF p_item = 'CTL.NEWPAY' THEN
      s := NULL;
      IF name_in('CTL.REG_CODE') IS NOT NULL THEN
        s := register_id;
      END IF;
      IF upper(name_in('CTL.P_KIND')) = 'P' THEN
        v := mm_core.pay(num('CTL.SUPP_ID'), num('CTL.P_AMOUNT'), upper(nvl(name_in('CTL.P_METHOD'), 'BANK')),
                         date_in('CTL.P_DATE'), s, name_in('CTL.P_NOTES'));
      ELSE
        v := mm_core.receive(num('CTL.CUST_ID'), num('CTL.P_AMOUNT'), upper(nvl(name_in('CTL.P_METHOD'), 'CASH')),
                             date_in('CTL.P_DATE'), s, name_in('CTL.P_NOTES'));
      END IF;
      forms_ddl('COMMIT');
      copy('', 'CTL.P_AMOUNT');
      copy('', 'CTL.P_NOTES');
      show_only(v);
      message(tx('TC7A5602F'));
    ELSIF p_item = 'CTL.CANCELPAY' THEN
      mm_core.cancel_payment(num('PAY.ID'));
      forms_ddl('COMMIT');
      again(c_block);
      message(tx('T21EA605F'));
    ELSIF p_item = 'CTL.DELDOC' THEN
      mm_core.delete_doc(num('DOC.ID'));
      forms_ddl('COMMIT');
      go_block(c_block);
      set_block_property(c_block, DEFAULT_WHERE, c_where);
      again(c_block);
      message(tx('T6113717A'));
    END IF;
  EXCEPTION
    WHEN form_trigger_failure THEN
      RAISE;
    WHEN OTHERS THEN
      forms_ddl('ROLLBACK');
      message(friendly(sqlerrm));
  END;

  -- the record chosen in the LOV "find", alone in the block; "all": every record again
  PROCEDURE press(p_item VARCHAR2) IS
    v VARCHAR2(40);
  BEGIN
    IF p_item = 'CTL.FIND' THEN
      copy('', 'CTL.FIND_ID');
      IF show_lov('LOV_FIND') THEN
        v := name_in('CTL.FIND_ID');
        IF v IS NOT NULL THEN
          go_block(c_block);
          set_block_property(c_block, DEFAULT_WHERE, 'id = ' || to_char(to_number(v)));
          g_master := NULL;
          execute_query;
          set_block_property(c_block, DEFAULT_WHERE, c_where);
        END IF;
      END IF;
    ELSIF p_item = 'CTL.ALL' THEN
      copy('', 'CTL.FIND_TEXT');
      go_block(c_block);
      set_block_property(c_block, DEFAULT_WHERE, c_where);
      g_master := NULL;
      execute_query;
    ELSE
      action(p_item);
    END IF;
  END;

  -- the toolbar: the keys of the Forms on the block of the cursor (the buttons do not take it)
  PROCEDURE tool(p_item VARCHAR2) IS
  BEGIN
    IF p_item = 'TB.T_SAVE' THEN
      do_key('COMMIT_FORM');
    ELSIF p_item = 'TB.T_ENTERQ' THEN
      do_key('ENTER_QUERY');
    ELSIF p_item = 'TB.T_EXECQ' THEN
      do_key('EXECUTE_QUERY');
    ELSIF p_item = 'TB.T_NEW' THEN
      do_key('CREATE_RECORD');
    ELSIF p_item = 'TB.T_DEL' THEN
      do_key('DELETE_RECORD');
    ELSIF p_item = 'TB.T_LOV' THEN
      do_key('LIST_VALUES');           -- the list of the item of the cursor
    ELSIF p_item = 'TB.T_PREV' THEN
      do_key('PREVIOUS_RECORD');
    ELSIF p_item = 'TB.T_NEXT' THEN
      do_key('NEXT_RECORD');
    ELSIF p_item = 'TB.T_MAIN' THEN
      new_form('MM_MAIN');
    ELSIF p_item = 'TB.T_EXIT' THEN
      do_key('EXIT_FORM');
    END IF;
  END;

  -- a double click on an item with a list: the list (F9 is not the key of the list on the web)
  PROCEDURE dblclick(p_item VARCHAR2) IS
  BEGIN
    IF p_item IS NOT NULL AND get_item_property(p_item, LOV_NAME) IS NOT NULL THEN
      do_key('LIST_VALUES');
    END IF;
  END;

  PROCEDURE validate(p_item VARCHAR2) IS
    v VARCHAR2(400) := name_in(p_item);
  BEGIN
    IF v IS NULL THEN
      RETURN;
    END IF;
    IF p_item = 'ITEM.BARCODE' THEN
      IF mm_core.ean_ok(v) = 'N' THEN
        fail(tx('T22238872'));
      END IF;
    ELSIF p_item IN ('ITEM.PRICE', 'ITEM.COST', 'ITEM.MIN_STOCK') THEN
      IF to_number(v) < 0 THEN
        fail(tx('TE70AB6C4'));
      END IF;
    ELSIF p_item = 'PARTNER.AFM' THEN
      IF mm_core.afm_ok(v) = 'N' THEN
        fail(tx('TEA0B7F9B'));
      END IF;
    ELSIF p_item = 'PARTNER.EMAIL' THEN
      IF v NOT LIKE '_%@_%._%' THEN
        fail(tx('T545A55C9'));
      END IF;
    END IF;
  END;

  -- what is not a column of the block: the name of the category, the rate of the VAT, the stock
  -- (MM_ITEM.STOCK is reservable and changes all day: not a database item, so the form never
  -- writes it and never sees "record changed by another user" for it)
  PROCEDURE post_query(p_block VARCHAR2) IS
    n VARCHAR2(200);
    z VARCHAR2(40);
    r NUMBER;
    s NUMBER;
    a NUMBER;
    id_ NUMBER;
    c_ NUMBER;
  BEGIN
    IF p_block = 'ITEM' THEN
      -- NAME_IN outside the SELECT: a built-in of the Forms "may not be used in SQL" (PL/SQL 231)
      id_ := to_number(name_in('ITEM.ID'));
      BEGIN
        SELECT c.name, v.rate, i.stock INTO n, r, s
        FROM mm_item i, mm_category c, mm_vat v
        WHERE i.id = id_ AND c.id = i.category_id AND v.code = i.vat_code;
        copy(n, 'ITEM.CAT_NAME');
        copy(to_char(r), 'ITEM.VAT_RATE');
        copy(to_char(s), 'ITEM.STOCK');
      EXCEPTION
        WHEN no_data_found THEN NULL;
      END;
    ELSIF p_block = 'CARD' THEN
      id_ := num('CARD.ID');
      SELECT stock INTO s FROM mm_item WHERE id = id_;
      copy(to_char(s), 'CARD.STOCK');
    ELSIF p_block = 'DOC' THEN
      c_ := num('DOC.CUSTOMER_ID');
      id_ := num('DOC.SUPPLIER_ID');
      n := NULL;
      IF c_ IS NOT NULL THEN
        SELECT name INTO n FROM mm_customer WHERE id = c_;
      ELSIF id_ IS NOT NULL THEN
        SELECT name INTO n FROM mm_supplier WHERE id = id_;
      END IF;
      copy(n, 'DOC.PARTNER_TEXT');
    ELSIF p_block = 'PAY' THEN
      c_ := num('PAY.CUSTOMER_ID');
      id_ := num('PAY.SUPPLIER_ID');
      n := NULL;
      IF c_ IS NOT NULL THEN
        SELECT name INTO n FROM mm_customer WHERE id = c_;
      ELSIF id_ IS NOT NULL THEN
        SELECT name INTO n FROM mm_supplier WHERE id = id_;
      END IF;
      copy(n, 'PAY.PARTNER_TEXT');
    ELSIF p_block = 'DL' THEN
      id_ := num('DL.ITEM_ID');
      SELECT code || ' ' || name INTO n FROM mm_item WHERE id = id_;
      copy(n, 'DL.ITEM_TEXT');
    ELSIF p_block = 'RL' THEN
      id_ := num('RL.ITEM_ID');
      SELECT code || ' ' || name INTO n FROM mm_item WHERE id = id_;
      copy(n, 'RL.ITEM_TEXT');
    ELSIF p_block = 'KIT' THEN
      id_ := num('KIT.ID');
      SELECT ready, can_make INTO s, a FROM mm_kit_avail WHERE kit_id = id_;
      copy(to_char(s), 'KIT.STOCK');
      copy(to_char(a), 'KIT.CAN_MAKE');
    ELSIF p_block = 'KC' THEN
      id_ := num('KC.COMPONENT_ID');
      SELECT code || ' ' || name, stock INTO n, s FROM mm_item WHERE id = id_;
      copy(n, 'KC.COMP_TEXT');
      copy(to_char(s), 'KC.COMP_STOCK');
    ELSIF p_block = 'PI' THEN
      -- (no SELECT inside a function: the PL/SQL of the Forms does not take it, PL/SQL 103)
      id_ := num('PI.ITEM_ID');
      c_ := num('PI.CATEGORY_ID');
      IF id_ IS NOT NULL THEN
        SELECT code || ' ' || name INTO n FROM mm_item WHERE id = id_;
      ELSE
        SELECT name INTO n FROM mm_category WHERE id = c_;
      END IF;
      copy(n, 'PI.TEXT');
    ELSIF p_block = 'VG' THEN
      id_ := num('VG.ID');
      SELECT c.name, sz.code, av.stock, av.available INTO n, z, s, a
      FROM mm_item v, mm_color c, mm_size sz, mm_item_avail av
      WHERE v.id = id_ AND c.id (+) = v.color_id AND sz.id (+) = v.size_id AND av.item_id = v.id;
      copy(n, 'VG.COLOR_TEXT');
      copy(z, 'VG.SIZE_TEXT');
      copy(to_char(s), 'VG.STOCK');
      copy(to_char(a), 'VG.AVAIL');
    END IF;
    -- what this procedure put in the items of the record is not a change of the user: the record
    -- as it came from the database (else a LOV that validates from its list writes its db item
    -- again when the cursor passes, and the form asks to save what nobody changed)
    set_record_property(to_number(name_in('SYSTEM.TRIGGER_RECORD')), p_block, STATUS, QUERY_STATUS);
  END;

  -- the messages of the database in words: the constraint by its name, MM_CORE as it is
  FUNCTION friendly(p_dbtext VARCHAR2) RETURN VARCHAR2 IS
    p PLS_INTEGER := instr(p_dbtext, 'MM-1');
    c VARCHAR2(128);
  BEGIN
    IF p > 0 THEN
      RETURN rtrim(substr(p_dbtext, p, instr(p_dbtext || chr(10), chr(10), p) - p));
    END IF;
    p := instr(p_dbtext, '(MM.');
    IF p > 0 THEN
      c := substr(p_dbtext, p + 4, instr(p_dbtext, ')', p) - p - 4);
    END IF;
    RETURN CASE c
      WHEN 'MM_ITEM_CODE_UK' THEN tx('TB806186A')
      WHEN 'MM_ITEM_BARCODE_UK' THEN tx('T1F4CE438')
      WHEN 'MM_ITEM_BARCODE_CK' THEN tx('T5E52D707')
      WHEN 'MM_ITEM_PRICE_CK' THEN tx('T49A1E700')
      WHEN 'MM_ITEM_COST_CK' THEN tx('T88ECCC37')
      WHEN 'MM_ITEM_MIN_CK' THEN tx('TA37878FE')
      WHEN 'MM_DOC_LINE_ITEM_FK' THEN tx('T1EC8273B')
      WHEN 'MM_STOCK_MOVE_ITEM_FK' THEN tx('T0179355B')
      WHEN 'MM_COUNT_LINE_ITEM_FK' THEN tx('T39B36DC5')
      WHEN 'MM_CUSTOMER_AFM_UK' THEN tx('TDA378DB0')
      WHEN 'MM_SUPPLIER_AFM_UK' THEN tx('T6E196C2F')
      WHEN 'MM_CUSTOMER_AFM_CK' THEN tx('T62053325')
      WHEN 'MM_SUPPLIER_AFM_CK' THEN tx('T62053325')
      WHEN 'MM_CUSTOMER_EMAIL_CK' THEN tx('T545A55C9')
      WHEN 'MM_SUPPLIER_EMAIL_CK' THEN tx('T545A55C9')
      WHEN 'MM_DOC_CUSTOMER_FK' THEN tx('TE0832A2F')
      WHEN 'MM_DOC_SUPPLIER_FK' THEN tx('TF37AAB64')
      ELSE p_dbtext
    END;
  END;

  PROCEDURE on_error(p_code NUMBER, p_type VARCHAR2, p_text VARCHAR2, p_dbtext VARCHAR2) IS
  BEGIN
    -- FRM-40508/40509/40510: insert, update, delete failed; the reason is in DBMS_ERROR_TEXT
    IF p_code IN (40508, 40509, 40510) AND p_dbtext IS NOT NULL THEN
      message(friendly(p_dbtext));
    ELSE
      message(p_type || '-' || to_char(p_code) || ': ' || p_text);
    END IF;
  END;
END;
